// Enumerate content-bearing WP REST types; emit ONE item per post (lightweight metadata).
// Collect ALL types first, sort GLOBALLY by modified asc, then take the oldest BATCH.
// Why: the global watermark must cover EVERY type. A type-major cap (fill 500 from 'pages'
// then advance the watermark) strands older items in later types behind the pages watermark.
const types = ['pages','posts','campaign','causes','awards','alumni_story','news','csr','allstory','casestudy','events_list','annual_report','annual_contributors','legacy_project','batch_legacy','jobs','dean_desk','dean_circle','leadership_circle','giving_circle','chairman_circle','director_circle'];
const base = 'https://acr.iitbombay.org/wp-json/wp/v2/';
const since = ($json.value ? String($json.value) : '1970-01-01T00:00:00');
const BATCH = 500; // memory throttle: N oldest-by-modified per run; watermark advances so re-runs resume.
const all = [];
for (const t of types) {
  let page = 1;
  while (true) {
    let items;
    try {
      items = await this.helpers.httpRequest({
        method: 'GET', url: base + t, json: true,
        qs: { status: 'publish', per_page: 100, page, modified_after: since, orderby: 'modified', order: 'asc', _fields: 'id,link,title,modified,status' }
      });
    } catch (e) { break; }
    if (!Array.isArray(items) || items.length === 0) break;
    for (const it of items) {
      if (it.id === 2) continue; // Sample Page
      const path = (() => { try { return new URL(it.link).pathname.replace(/\/$/, ''); } catch { return String(it.link || '').replace(/\/$/, ''); } })();
      const title = (it.title && it.title.rendered) ? it.title.rendered : '';
      all.push({ json: { post_id: it.id, source_type: t, url: it.link, path, title, modified: it.modified } });
    }
    if (items.length < 100) break;
    page++;
  }
}
// Global oldest-first sort so the batch + watermark span ALL types uniformly.
all.sort((a, b) => (a.json.modified < b.json.modified ? -1 : a.json.modified > b.json.modified ? 1 : 0));
// Cap to BATCH, but extend to include ALL items sharing the boundary timestamp so no tie is
// stranded when the watermark (exclusive modified_after) advances past that second.
let end = Math.min(BATCH, all.length);
while (end < all.length && all[end].json.modified === all[end - 1].json.modified) end++;
const batch = all.slice(0, end);
// Watermark = newest modified in the batch. Safe: every item across ALL types with
// modified <= this was included, so nothing older is skipped next run.
const finalMax = batch.length ? batch[batch.length - 1].json.modified : since;
for (const o of batch) o.json._maxModified = finalMax;
return batch;

// Header-aware sectioning of trafilatura markdown -> chunk items.
// Match each Trafilatura item back to its Enumerate metadata BY URL (index-safe: a
// Filter node upstream may drop items, so positions no longer line up).
function sectionize(md) {
  const lines = String(md).split('\n');
  const secs = [];
  let cur = { heading: '', body: [] };
  for (const ln of lines) {
    const m = ln.match(/^(#{1,6})\s+(.*)$/);
    if (m) {
      if (cur.heading || cur.body.join('').trim()) secs.push(cur);
      cur = { heading: m[2].trim(), body: [] };
    } else { cur.body.push(ln); }
  }
  if (cur.heading || cur.body.join('').trim()) secs.push(cur);
  return secs.length ? secs : [{ heading: '', body: [String(md)] }];
}
// CONFIG: min real-content chars to keep a page (menu/junk pages fall below this).
const MIN_CONTENT_CHARS = 200;
const items = $input.all();
const byUrl = new Map($('Skip Synced').all().map(x => [x.json.url, x.json]));
const out = [];
for (let i = 0; i < items.length; i++) {
  const md = (items[i].json && items[i].json.markdown) ? items[i].json.markdown : '';
  const s0 = byUrl.get(items[i].json.url) || items[i].json;
  // Backstop: skip near-empty extractions (blocklist handled by the Filter node).
  // ponytail: char floor is a heuristic; raise if real short pages get dropped.
  if (String(md).trim().length < MIN_CONTENT_CHARS) continue;
  const title = s0.title || '';
  const secs = sectionize(md);
  const outline = secs.map(s => s.heading).filter(Boolean).join(' | ');
  let ci = 0;
  for (const s of secs) {
    const body = s.body.join('\n').trim();
    if (!body && !s.heading) continue;
    const heading = s.heading || title;
    const content = (title + (s.heading ? ' — ' + s.heading : '') + '\n\n' + body).trim();
    out.push({ json: { post_id: s0.post_id, source_type: s0.source_type, url: s0.url, title, modified: s0.modified, section_heading: heading, chunk_index: ci, outline, content, _maxModified: s0._maxModified } });
    ci++;
  }
}
if (out.length === 0) {
  // ponytail: all-junk batch -> emit watermark-only sentinel so Update Watermark still advances
  // (else the run dead-ends at 0 items and the watermark freezes on the same oldest window forever).
  // Ceiling: an all-already-synced batch (Skip Synced=0) never reaches this node; handle if it appears.
  const s = $('Skip Synced').first();
  const wm = s && s.json ? s.json._maxModified : null;
  return [{ json: { _watermark_only: true, _maxModified: wm } }];
}
return out;

const src = $('Restore Items').all();
const ai = $input.all();
return src.map((s, i) => {
  let ctx = '';
  try { ctx = String(ai[i].json.text).trim(); } catch (e) { ctx = ''; }
  const j = { ...s.json };
  j.context = ctx;
  j.content = ctx ? (ctx + '\n\n' + j.content) : j.content;
  return { json: j };
});

// Drop pages already in DB with unchanged 'modified'; keep new + changed.
// ponytail: modified compared as exact string; false-'changed' at worst re-embeds a few, never data loss.
const synced = new Map($('Get Synced').all().map(r => [String(r.json.post_id) + '|' + r.json.source_type, r.json.modified]));
return $('Enumerate WP').all().filter(it => {
  const key = String(it.json.post_id) + '|' + it.json.source_type;
  const prev = synced.get(key);
  return prev === undefined || prev !== it.json.modified;
});
